package lol.pyr.znpcsplus.fabric.npc;
import lol.pyr.znpcsplus.fabric.util.NpcLocation;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
public final class NpcRegistry{private final Map<String,Npc> byId=new ConcurrentHashMap<>();private final Map<Integer,Npc> byEntityId=new ConcurrentHashMap<>();private final AtomicInteger ids=new AtomicInteger(1900000000);
 public synchronized Npc create(String id,String world,String type,NpcLocation loc){String k=norm(id);if(byId.containsKey(k))throw new IllegalArgumentException("NPC with that ID already exists");Npc n=new Npc(k,world,type,loc);reserve(n);byId.put(k,n);return n;}public synchronized void register(Npc n){n.id=norm(n.id);reserve(n);byId.put(n.id,n);}public synchronized void registerAll(Collection<Npc> c){for(Npc n:c)register(n);}public synchronized Npc delete(String id){Npc n=byId.remove(norm(id));if(n!=null)byEntityId.remove(n.entityId);return n;}public synchronized boolean changeId(String o,String ne){String a=norm(o),b=norm(ne);if(byId.containsKey(b))return false;Npc n=byId.remove(a);if(n==null)return false;n.id=b;byId.put(b,n);return true;}public Npc get(String id){return id==null?null:byId.get(norm(id));}public Npc byEntityId(int id){return byEntityId.get(id);}public Collection<Npc> all(){return Collections.unmodifiableCollection(byId.values());}public Set<String> ids(){return Collections.unmodifiableSet(new TreeSet<>(byId.keySet()));}public synchronized void clear(){byId.clear();byEntityId.clear();}public int size(){return byId.size();}public int nextPacketId(){return ids.getAndDecrement();}
 private void reserve(Npc n){if(n.entityId==0)n.entityId=ids.getAndDecrement();byEntityId.put(n.entityId,n);}private static String norm(String s){if(s==null||s.isBlank())throw new IllegalArgumentException("NPC ID cannot be blank");return s.toLowerCase(Locale.ROOT);}
}